    if not m or not 1 <= int(m.group(2)) <= 999:
        raise ValueError(f"bad cell name: {cell!r}")
    return cell


class Sheet:
    def __init__(self):
        self._raw = {}

    def set(self, cell, raw):
        _check_cell(cell)
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        raw = self._raw.get(cell)
        if raw is None:
            return None
        return self._literal(raw)

    @staticmethod
    def _literal(raw):
        if _INT.fullmatch(raw):
            return int(raw)
        if _FLOAT.fullmatch(raw):
            return float(raw)
        return raw

